import{_ as a,o,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Guía del usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/index.md","filePath":"es-ES/user-guide/index.md","lastUpdated":1788366161000}'),i={name:"es-ES/user-guide/index.md"};function t(n,e,d,l,c,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="guia-del-usuario" tabindex="-1">Guía del usuario <a class="header-anchor" href="#guia-del-usuario" aria-label="Permalink to &quot;Guía del usuario&quot;">​</a></h1><p>¡Te damos la bienvenida a la Guía oficial del usuario de Lertaro! Lertaro es un lanzador de búsqueda de archivos ultrarrápido y una herramienta de productividad diseñada a medida para Windows. Al mantener un árbol de índices en memoria en segundo plano (mediante diarios de cambios USN de NTFS/ReFS y eventos del sistema de archivos en tiempo real), ofrece respuestas de búsqueda en submilisegundos en millones de archivos.</p><p>Esta guía cubre de forma sistemática todas las funciones esenciales y avanzadas necesarias para tu flujo de trabajo:</p><ul><li><strong><a href="./getting-started.html">Primeros pasos</a></strong> —— Instalación, versión portátil, resumen de arquitectura, tres modalidades de ventana (Rápida / Principal / Incrustada) y operaciones básicas.</li><li><strong><a href="./search-syntax.html">Sintaxis de búsqueda</a></strong> —— Coincidencia difusa, operadores (<code>!</code> exclusión, <code>&#39;</code> exacta, <code>^</code> prefijo, <code>$</code> sufijo, <code>|</code> OR), prefijos de unidad, modo ruta y alias de pinyin.</li><li><strong><a href="./hotkeys.html">Atajos de teclado y gestos</a></strong> —— Tabla de atajos globales, gestos de ratón en el logotipo, menús en cascada de Navegación rápida y teclas fijas.</li><li><strong><a href="./actions-and-preview.html">Acciones y vista previa</a></strong> —— Menú contextual de acciones (<code>Ctrl+O</code>), lista de la Ventana principal, vista previa multimedia/documentos con QuickLook y tarjetas de plugins.</li><li><strong><a href="./space-analyzer.html">Analizador de espacio</a></strong> —— Visualización Treemap con latencia cero y desglose ordenado por tamaño para limpiar almacenamiento.</li><li><strong><a href="./instant-answers.html">Respuestas instantáneas y funciones con palabras clave</a></strong> —— Calculadora, variables de entorno, comandos y plugins como Gestor de procesos (<code>ps</code>), Conmutador de ventanas (<code>win</code>), Marcadores del navegador (<code>bb</code>), Historial del navegador (<code>bh</code>) y Configuración (<code>set</code>).</li><li><strong><a href="./cli.html">Búsqueda por línea de comandos (lff)</a></strong> —— Buscador difuso interactivo para terminal que comparte el índice en memoria para scripts y tuberías.</li><li><strong><a href="./uri-protocol.html">Protocolo URI (lertaro://)</a></strong> —— Enlaces directos desde navegadores, accesos directos y scripts hacia búsquedas, configuración y transferencias LocalSend.</li><li><strong><a href="./file-manager-support.html">Exploradores de archivos compatibles</a></strong> —— Integración con diálogos de Windows, Directory Opus, Total Commander, XYplorer, Files y One Commander.</li><li><strong><a href="./settings/">Referencia de configuración</a></strong> —— Desglose completo de Estado del servicio, Indexación, General, Apariencia, Atajos y Plugins.</li><li><strong><a href="./troubleshooting.html">Solución de problemas</a></strong> —— Guía paso a paso para diagnosticar atajos, indexación, métodos de entrada (IME) y consulta de registros.</li><li><strong><a href="./donate.html">Donaciones y apoyo</a></strong> —— Apoya el desarrollo continuo y el mantenimiento de código abierto de Lertaro.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Si es la primera vez que utilizas Lertaro, te recomendamos comenzar por <a href="./getting-started.html"><strong>Primeros pasos</strong></a>.</p></div>',5)])])}const g=a(i,[["render",t]]);export{m as __pageData,g as default};
